def magic_square_test(matrix):
    if not matrix or not matrix[0]:
        return False

    n = len(matrix)
    m = len(matrix[0])

    if n != m:
        return False

    def calculate_sum(matrix, n):
        sums = [0] * n
        for i in range(n):
            sums[i] = sum(matrix[i])
        for i in range(n):
            for j in range(n):
                sums[i] += matrix[i][j]

    sums = [sum(matrix[i]) for i in range(n)]
    col_sums = [sum(matrix[j][i] for j in range(n)) for i in range(n)]
    diag1_sum = sum(matrix[i][i] for i in range(n))
    diag2_sum = sum(matrix[i][n - 1 - i] for i in range(n))

    magic_sum = sums[0]

    for row_sum in sums:
        if row_sum != magic_sum:
            return False

    for col_sum in col_sums:
        if col_sum != magic_sum:
            return False

    if diag1_sum != magic_sum or diag2_sum != magic_sum:
        return False

    return True

